import 'package:flutter/material.dart';

/// The destructive button role (S5.2). The primary (filled), secondary
/// (outlined) and tertiary (text) roles come from the theme's button
/// themes; a destructive action adds one of these styles. See
/// `docs/DESIGN_SYSTEM.md`, "Buttons".
abstract final class AppButtonStyles {
  /// A destructive action that is the screen's main action.
  static ButtonStyle destructive(ColorScheme scheme) => FilledButton.styleFrom(
    backgroundColor: scheme.error,
    foregroundColor: scheme.onError,
  );

  /// A destructive action beside Cancel in a dialog.
  static ButtonStyle destructiveText(ColorScheme scheme) =>
      TextButton.styleFrom(foregroundColor: scheme.error);
}

import 'package:flutter/material.dart';

/// The raw colours behind the three themes. Widgets never read these
/// directly: they use `Theme.of(context).colorScheme` or [AppPalette]
/// (TASK 12.4). The text roles (S5.1) are documented in
/// `docs/DESIGN_SYSTEM.md`: in light and dark every role is WCAG AA
/// (4.5:1) on the background, the surface and the raised surface, and each
/// is at least 1.3 times the next one's contrast. Control borders (S5.2)
/// are at least 3:1 (WCAG 1.4.11); the error colour is AA as text.
class AppColors {
  // The Culmina mark's colours are generated with its geometry
  // (lib/presentation/shared/culmina_mark_geometry.dart, tool/culmina_mark.py).

  // Light Theme
  static const Color lightBackground = Color(0xFFFFFFFF);
  static const Color lightSurface = Color(0xFFF7F7F5);
  static const Color lightSurfaceRaised = Color(0xFFFFFFFF);
  static const Color lightTextPrimary = Color(0xFF37352F); // 11.4:1
  static const Color lightTextSecondary = Color(0xFF5A5955); // 6.5:1
  static const Color lightTextTertiary = Color(0xFF6E6D69); // 4.8:1
  static const Color lightTextDisabled = Color(0xFFA3A29F);
  static const Color lightBorder = Color(0xFFE9E9E7);
  static const Color lightControlBorder = Color(0xFF8F8E8A); // 3.1:1
  static const Color lightError = Color(0xFFB00020); // 6.8:1

  // Dark Theme
  static const Color darkBackground = Color(0xFF191919);
  static const Color darkSurface = Color(0xFF202020);
  static const Color darkSurfaceRaised = Color(0xFF252525);
  static const Color darkTextPrimary = Color(0xFFEBEBEA); // 12.8:1
  static const Color darkTextSecondary = Color(0xFFA5A5A3); // 6.2:1
  static const Color darkTextTertiary = Color(0xFF8F8F8D); // 4.7:1
  static const Color darkTextDisabled = Color(0xFF6B6B69);
  static const Color darkSelection = Color(0xFF343432);
  static const Color darkBorder = Color(0xFF2F2F2F);
  static const Color darkControlBorder = Color(0xFF6F6F6D); // 3.0:1
  static const Color darkError = Color(0xFFF28B82); // 6.4:1

  // Field Mode (Red): brightness, not hue, separates the roles.
  static const Color fieldBackground = Color(0xFF000000);
  static const Color fieldSurface = Color(0xFF110000);
  static const Color fieldSurfaceRaised = Color(0xFF1A0000);
  static const Color fieldTextPrimary = Color(0xFFFF0000);
  static const Color fieldTextSecondary = Color(0xFFAA0000);
  static const Color fieldTextTertiary = Color(0xFF880000);
  static const Color fieldTextDisabled = Color(0xFF660000);
  static const Color fieldBorder = Color(0xFF330000);
  // Brighter than a card border so controls stay visible (UX-39).
  static const Color fieldControlBorder = Color(0xFF880000);
}

import 'package:flutter/widgets.dart';

/// The motion scale (S5.2): short, subtle transitions only
/// (`.agents/rules/05-ui-design.md`). Every animated component asks
/// [duration] for its length, so the platform's reduced-motion setting
/// turns motion off. See `docs/DESIGN_SYSTEM.md`.
abstract final class AppMotion {
  /// A state change in place: a pressed control, a chevron turning.
  static const Duration short = Duration(milliseconds: 120);

  /// Content appearing or collapsing: a section opening, a row leaving.
  static const Duration medium = Duration(milliseconds: 180);

  /// A brief mark on what an edit changed, fading out (S6.9: a capture
  /// block just added or edited). Long enough to be seen, never repeated.
  static const Duration highlight = Duration(milliseconds: 1500);

  /// The one curve: fast out, gentle in.
  static const Curve curve = Cubic(0.16, 1, 0.3, 1);

  /// [base], or zero when the user asked the platform for less motion.
  static Duration duration(BuildContext context, Duration base) =>
      MediaQuery.maybeDisableAnimationsOf(context) ?? false
      ? Duration.zero
      : base;
}

import 'package:flutter/material.dart';

import 'app_colors.dart';

/// Semantic colour tokens that the Material [ColorScheme] has no role for
/// (TASK 12.4): muted text, the night's events, the altitude chart and the
/// Bortle scale. Widgets read them with [AppPalette.of]; `lib/presentation`
/// never names a colour itself (a test enforces it). Field mode's tokens
/// are red or black only.
@immutable
class AppPalette extends ThemeExtension<AppPalette> {
  const AppPalette({
    required this.textPrimary,
    required this.textSecondary,
    required this.textTertiary,
    required this.textDisabled,
    required this.surfaceRaised,
    required this.border,
    required this.controlBorder,
    required this.statusFits,
    required this.statusTight,
    required this.statusDoesNotFit,
    required this.statusNoWindow,
    required this.statusNeutral,
    required this.stateUnsaved,
    required this.stateSettled,
    required this.stateQuiet,
    required this.muted,
    required this.caution,
    required this.sunEvent,
    required this.twilightEvent,
    required this.moon,
    required this.selected,
    required this.chartDay,
    required this.chartTwilight,
    required this.chartDark,
    required this.chartWindow,
    required this.chartTarget,
    required this.chartMoon,
    required this.chartMinAltitude,
    required this.chartNow,
    required this.chartNowCentre,
    required this.chartGrid,
    required this.chartLabel,
    required this.swatchBorder,
    required this.bortle,
    required this.onBortle,
  });

  /// The text roles (S5.1; `docs/DESIGN_SYSTEM.md`): primary for the
  /// answer and values, secondary for labels and supporting text, tertiary
  /// for captions and metadata. In light and dark each is WCAG AA on the
  /// background, the surface and [surfaceRaised]; disabled is exempt (WCAG
  /// 1.4.3 excludes inactive controls).
  final Color textPrimary;
  final Color textSecondary;
  final Color textTertiary;
  final Color textDisabled;

  /// Dialogs, menus and sheets: one level above the card surface.
  final Color surfaceRaised;

  /// Card and section outlines; dividers (decorative).
  final Color border;

  /// The boundary of a control (S5.2): a text field's underline or
  /// outline, an outlined button. At least 3:1 in light and dark (WCAG
  /// 1.4.11); in field mode brighter than [border] (UX-39).
  final Color controlBorder;

  /// The verdict's colours (S5.4; UX-16): each `FitState` has one. A real
  /// verdict is coloured; a missing input ([statusNeutral]) is not. "Tight"
  /// is a caution at least as prominent as "Fits" (S1.9); in field mode all
  /// are red and the word carries the difference.
  final Color statusFits;
  final Color statusTight;
  final Color statusDoesNotFit;
  final Color statusNoWindow;
  final Color statusNeutral;

  /// The plan-state label's tones (S5.4; ADR-019 §3): unsaved work draws
  /// attention (Not saved, Saved · changed); a settled plan reads as
  /// primary text (Saved, Tracking, Completed); the rest is quiet (Partly,
  /// Not done, Old log). Tones, never verdicts.
  final Color stateUnsaved;
  final Color stateSettled;
  final Color stateQuiet;

  /// Secondary text and icons for empty or unknown states.
  final Color muted;

  /// A caution that is not an error, such as a "Tight" fit (S1.9): at least
  /// as prominent as body text.
  final Color caution;

  /// Sunset/sunrise and astronomical dusk/dawn icons.
  final Color sunEvent;
  final Color twilightEvent;

  /// The Moon icon.
  final Color moon;

  /// The check mark on the selected rig or target.
  final Color selected;

  /// Altitude chart: darkness bands, imaging windows, lines and labels.
  final Color chartDay;
  final Color chartTwilight;
  final Color chartDark;
  final Color chartWindow;
  final Color chartTarget;
  final Color chartMoon;
  final Color chartMinAltitude;
  final Color chartNow;
  final Color chartNowCentre;
  final Color chartGrid;
  final Color chartLabel;

  /// The outline of the chart legend's swatches and of the Bortle badge.
  final Color swatchBorder;

  /// Bortle badge background and text: index 0 is "unknown", 1–9 the class.
  final List<Color> bortle;
  final List<Color> onBortle;

  static AppPalette of(BuildContext context) =>
      Theme.of(context).extension<AppPalette>() ?? light;

  // The accepted web cascade's caution role (notion-hybrid.css, 86873ce).
  static const _lightCaution = Color(0xFF754600); // 8.0:1 on white
  static const _darkCaution = Color(0xFFFFCA70); // 11.7:1 on #191919

  static const light = AppPalette(
    statusFits: AppColors.lightTextPrimary,
    statusTight: _lightCaution,
    statusDoesNotFit: AppColors.lightError,
    statusNoWindow: AppColors.lightError,
    statusNeutral: AppColors.lightTextSecondary,
    stateUnsaved: _lightCaution,
    stateSettled: AppColors.lightTextPrimary,
    stateQuiet: AppColors.lightTextSecondary,
    textPrimary: AppColors.lightTextPrimary,
    textSecondary: AppColors.lightTextSecondary,
    textTertiary: AppColors.lightTextTertiary,
    textDisabled: AppColors.lightTextDisabled,
    surfaceRaised: AppColors.lightSurfaceRaised,
    border: AppColors.lightBorder,
    controlBorder: AppColors.lightControlBorder,
    muted: Colors.grey,
    caution: _lightCaution, // 5.4:1 on white, 5.0:1 on the surface (AA)
    sunEvent: Colors.orange,
    twilightEvent: Colors.indigo,
    moon: Colors.blueGrey,
    selected: Colors.blue,
    chartDay: Color(0xFFB3E5FC), // lightBlue.shade100
    chartTwilight: Color(0xFF7986CB), // indigo.shade300
    chartDark: Colors.black87,
    chartWindow: Color(0x6600C853),
    chartTarget: Colors.amber,
    chartMoon: Color(0xFFB0BEC5), // blueGrey.shade200
    chartMinAltitude: Colors.redAccent,
    chartNow: Colors.redAccent,
    chartNowCentre: Colors.white,
    chartGrid: Colors.white60,
    chartLabel: Colors.white,
    swatchBorder: Color(0xFFBDBDBD), // grey.shade400
    bortle: _bortleColours,
    onBortle: _onBortleColours,
  );

  static const dark = AppPalette(
    statusFits: AppColors.darkTextPrimary,
    statusTight: _darkCaution,
    statusDoesNotFit: AppColors.darkError,
    statusNoWindow: AppColors.darkError,
    statusNeutral: AppColors.darkTextSecondary,
    stateUnsaved: _darkCaution,
    stateSettled: AppColors.darkTextPrimary,
    stateQuiet: AppColors.darkTextSecondary,
    textPrimary: AppColors.darkTextPrimary,
    textSecondary: AppColors.darkTextSecondary,
    textTertiary: AppColors.darkTextTertiary,
    textDisabled: AppColors.darkTextDisabled,
    surfaceRaised: AppColors.darkSurfaceRaised,
    border: AppColors.darkBorder,
    controlBorder: AppColors.darkControlBorder,
    muted: Colors.grey,
    caution: _darkCaution,
    sunEvent: Colors.orange,
    twilightEvent: Colors.indigo,
    moon: Colors.blueGrey,
    selected: Colors.blue,
    chartDay: Color(0xFF37474F), // blueGrey.shade800
    chartTwilight: Color(0xFF1A237E), // indigo.shade900
    chartDark: Colors.black,
    chartWindow: Color(0x6600C853),
    chartTarget: Colors.amber,
    chartMoon: Color(0xFFB0BEC5),
    chartMinAltitude: Colors.redAccent,
    chartNow: Colors.redAccent,
    chartNowCentre: Colors.white,
    chartGrid: Colors.white30,
    chartLabel: Colors.white70,
    swatchBorder: Color(0xFFBDBDBD),
    bortle: _bortleColours,
    onBortle: _onBortleColours,
  );

  /// Red on black only: brightness, not hue, tells elements apart.
  static const field = AppPalette(
    statusFits: AppColors.fieldTextPrimary,
    statusTight: AppColors.fieldTextPrimary,
    statusDoesNotFit: AppColors.fieldTextPrimary,
    statusNoWindow: AppColors.fieldTextPrimary,
    statusNeutral: AppColors.fieldTextSecondary,
    stateUnsaved: AppColors.fieldTextPrimary,
    stateSettled: AppColors.fieldTextPrimary,
    stateQuiet: AppColors.fieldTextSecondary,
    textPrimary: AppColors.fieldTextPrimary,
    textSecondary: AppColors.fieldTextSecondary,
    textTertiary: AppColors.fieldTextTertiary,
    textDisabled: AppColors.fieldTextDisabled,
    surfaceRaised: AppColors.fieldSurfaceRaised,
    border: AppColors.fieldBorder,
    controlBorder: AppColors.fieldControlBorder,
    muted: AppColors.fieldTextSecondary,
    // As bright as "Fits": in red mode the word carries the caution.
    caution: AppColors.fieldTextPrimary,
    sunEvent: AppColors.fieldTextPrimary,
    twilightEvent: AppColors.fieldTextSecondary,
    moon: AppColors.fieldTextSecondary,
    selected: AppColors.fieldTextPrimary,
    chartDay: Color(0xFF3A0000),
    chartTwilight: Color(0xFF1C0000),
    chartDark: AppColors.fieldBackground,
    chartWindow: Color(0x55FF0000),
    chartTarget: AppColors.fieldTextPrimary,
    chartMoon: Color(0xFF990000),
    chartMinAltitude: Color(0xFFCC0000),
    chartNow: AppColors.fieldTextPrimary,
    chartNowCentre: AppColors.fieldBackground,
    chartGrid: Color(0x66FF0000),
    chartLabel: Color(0xFFCC0000),
    swatchBorder: AppColors.fieldBorder,
    bortle: [
      Color(0xFF330000),
      Color(0xFF110000),
      Color(0xFF220000),
      Color(0xFF330000),
      Color(0xFF440000),
      Color(0xFF660000),
      Color(0xFF880000),
      Color(0xFFAA0000),
      Color(0xFFCC0000),
      Color(0xFFFF0000),
    ],
    onBortle: [
      AppColors.fieldTextPrimary,
      AppColors.fieldTextPrimary,
      AppColors.fieldTextPrimary,
      AppColors.fieldTextPrimary,
      AppColors.fieldTextPrimary,
      AppColors.fieldTextPrimary,
      AppColors.fieldBackground,
      AppColors.fieldBackground,
      AppColors.fieldBackground,
      AppColors.fieldBackground,
    ],
  );

  /// The conventional Bortle map colours (unchanged from before TASK 12.4).
  static const _bortleColours = [
    Colors.grey,
    Colors.black,
    Color(0xFF263238), // blueGrey.shade900
    Color(0xFF0D47A1), // blue.shade900
    Color(0xFF388E3C), // green.shade700
    Color(0xFFFBC02D), // yellow.shade700
    Colors.orange,
    Colors.deepOrange,
    Colors.red,
    Colors.white,
  ];
  static const _onBortleColours = [
    Colors.white,
    Colors.white,
    Colors.white,
    Colors.white,
    Colors.white,
    Colors.black,
    Colors.white,
    Colors.white,
    Colors.white,
    Colors.red,
  ];

  /// Every token, for tests.
  List<Color> get all => [
    textPrimary,
    textSecondary,
    textTertiary,
    textDisabled,
    surfaceRaised,
    border,
    controlBorder,
    statusFits,
    statusTight,
    statusDoesNotFit,
    statusNoWindow,
    statusNeutral,
    stateUnsaved,
    stateSettled,
    stateQuiet,
    muted,
    caution,
    sunEvent,
    twilightEvent,
    moon,
    selected,
    chartDay,
    chartTwilight,
    chartDark,
    chartWindow,
    chartTarget,
    chartMoon,
    chartMinAltitude,
    chartNow,
    chartNowCentre,
    chartGrid,
    chartLabel,
    swatchBorder,
    ...bortle,
    ...onBortle,
  ];

  @override
  AppPalette copyWith() => this;

  @override
  AppPalette lerp(AppPalette? other, double t) =>
      other == null || t < 0.5 ? this : other;
}

/// Corner radii (S5.1), in logical pixels. One scale for the whole app;
/// see `docs/DESIGN_SYSTEM.md`.
abstract final class AppRadius {
  /// Cards, sections, text fields and buttons.
  static const double small = 6;

  /// Menus (plan.css `.plan-menu`).
  static const double menu = 8;

  /// Dialogs, bottom sheets and a swiped row's background.
  static const double large = 12;

  /// Pills and chips.
  static const double pill = 999;
}

/// The spacing scale, in logical pixels (documented in S5.1; see
/// `docs/DESIGN_SYSTEM.md`). Component padding and page gutters are distinct:
/// [md] is the usual card's inner padding, not a universal page gutter.
/// Current page callers generally use [gutter], with documented local exceptions.
/// [lg] separates sections; [sm] separates rows within a section;
/// [xs] separates a label from its value.
class AppSpacing {
  static const double xs = 4.0;
  static const double sm = 8.0;
  static const double md = 16.0;
  static const double lg = 24.0;
  static const double xl = 32.0;
  static const double xxl = 48.0;

  // Hybrid reference steps (notion-hybrid.css / conditions.css, CSS px as
  // logical px) used where the transferred screens follow the reference.
  /// A caption tucked under its line.
  static const double hair = 2.0;

  /// A secondary line under a value.
  static const double nudge = 3.0;

  /// A dense table cell's vertical padding.
  static const double cellY = 6.0;

  /// A note under a chart or list.
  static const double notes = 10.0;

  /// Between related items in a group.
  static const double itemGap = 12.0;

  /// A list row's vertical padding.
  static const double rowY = 14.0;

  /// A Hybrid page's side padding.
  static const double gutter = 20.0;

  /// Between sections of a Hybrid page.
  static const double section = 28.0;
}

import 'package:flutter/material.dart';
import 'package:flutter/cupertino.dart' show CupertinoPageTransitionsBuilder;

import 'app_colors.dart';
import 'app_palette.dart';
import 'app_radius.dart';
import 'app_spacing.dart';
import 'app_typography.dart';
import 'app_motion.dart';
import 'hybrid_tokens.dart';
import 'hybrid_view_entrance.dart';

/// The app's three themes (TASK 12.4): light, dark and red field mode.
/// Colours come from [AppColors] and [AppPalette] tokens; text is never
/// smaller than 12 sp in the base scale (HybridTokens names the compact
/// navigation/calendar exceptions). Since S5.1 text roles drive the colour scheme
/// (`onSurface` is the primary text, `onSurfaceVariant` and `secondary`
/// the secondary text), `surfaceContainerHigh` is the raised surface, and
/// [AppTypography.scale] sets every style's size and weight.
class AppTheme {
  /// The family of the styles the theme builds by hand (F25).
  static const _family = HybridTokens.fontFamily;

  static final ThemeData light = _withTokens(
    ThemeData(
      fontFamily: _family,
      brightness: Brightness.light,
      primaryColor: AppColors.lightTextPrimary,
      scaffoldBackgroundColor: AppColors.lightBackground,
      appBarTheme: const AppBarTheme(
        backgroundColor: AppColors.lightBackground,
        foregroundColor: AppColors.lightTextPrimary,
        elevation: 0,
        scrolledUnderElevation: 0,
        centerTitle: false,
        toolbarHeight: HybridTokens.appBarHeight,
        titleTextStyle: TextStyle(
          // Owner-selected bundled family, including Ukrainian glyphs.
          fontFamily: _family,
          color: AppColors.lightTextPrimary,
          fontSize: 22,
          height: 1.25,
          fontWeight: FontWeight.w500,
        ),
      ),
      colorScheme: const ColorScheme.light(
        primary: AppColors.lightTextPrimary,
        onPrimary: AppColors.lightBackground,
        secondary: AppColors.lightTextSecondary,
        // Selected segments and the navigation indicator: a light fill
        // with primary text (Material would derive them from secondary).
        secondaryContainer: AppColors.lightBorder,
        onSecondaryContainer: AppColors.lightTextPrimary,
        surface: AppColors.lightSurface,
        onSurface: AppColors.lightTextPrimary,
        onSurfaceVariant: AppColors.lightTextSecondary,
        surfaceContainerHigh: AppColors.lightSurfaceRaised,
        // S5.2: Material falls back to black for both (the prominent
        // field underline of 08 §6).
        outline: AppColors.lightControlBorder,
        outlineVariant: AppColors.lightBorder,
        error: AppColors.lightError,
      ),
      dividerTheme: const DividerThemeData(
        color: AppColors.lightBorder,
        thickness: 1,
        space: 1,
      ),
      cardTheme: CardThemeData(
        color: AppColors.lightSurface,
        elevation: 0,
        shape: RoundedRectangleBorder(
          borderRadius: BorderRadius.circular(AppRadius.small),
          side: const BorderSide(color: AppColors.lightBorder),
        ),
        margin: EdgeInsets.zero,
      ),
    ),
    AppPalette.light,
  );

  static final ThemeData dark = _withTokens(
    ThemeData(
      fontFamily: _family,
      brightness: Brightness.dark,
      primaryColor: AppColors.darkTextPrimary,
      scaffoldBackgroundColor: AppColors.darkBackground,
      appBarTheme: const AppBarTheme(
        backgroundColor: AppColors.darkBackground,
        foregroundColor: AppColors.darkTextPrimary,
        elevation: 0,
        scrolledUnderElevation: 0,
        centerTitle: false,
        toolbarHeight: HybridTokens.appBarHeight,
        titleTextStyle: TextStyle(
          // Owner-selected bundled family, including Ukrainian glyphs.
          fontFamily: _family,
          color: AppColors.darkTextPrimary,
          fontSize: 22,
          height: 1.25,
          fontWeight: FontWeight.w500,
        ),
      ),
      colorScheme: const ColorScheme.dark(
        primary: AppColors.darkTextPrimary,
        onPrimary: AppColors.darkBackground,
        secondaryContainer: AppColors.darkSelection,
        onSecondaryContainer: AppColors.darkTextPrimary,
        secondary: AppColors.darkTextSecondary,
        surface: AppColors.darkSurface,
        onSurface: AppColors.darkTextPrimary,
        onSurfaceVariant: AppColors.darkTextSecondary,
        surfaceContainerHigh: AppColors.darkSurfaceRaised,
        // S5.2: Material falls back to white for both.
        outline: AppColors.darkControlBorder,
        outlineVariant: AppColors.darkBorder,
        error: AppColors.darkError,
        onError: AppColors.darkBackground,
      ),
      dividerTheme: const DividerThemeData(
        color: AppColors.darkBorder,
        thickness: 1,
        space: 1,
      ),
      cardTheme: CardThemeData(
        color: AppColors.darkSurface,
        elevation: 0,
        shape: RoundedRectangleBorder(
          borderRadius: BorderRadius.circular(AppRadius.small),
          side: const BorderSide(color: AppColors.darkBorder),
        ),
        margin: EdgeInsets.zero,
      ),
    ),
    AppPalette.dark,
  );

  /// Every colour role is red or black (TASK 12.4), so dialogs, date
  /// pickers, snackbars, menus and the navigation bar stay red too.
  static const ColorScheme fieldColorScheme = ColorScheme(
    brightness: Brightness.dark,
    primary: AppColors.fieldTextPrimary,
    onPrimary: AppColors.fieldBackground,
    primaryContainer: AppColors.fieldBorder,
    onPrimaryContainer: AppColors.fieldTextPrimary,
    secondary: AppColors.fieldTextSecondary,
    onSecondary: AppColors.fieldBackground,
    secondaryContainer: AppColors.fieldBorder,
    onSecondaryContainer: AppColors.fieldTextPrimary,
    tertiary: AppColors.fieldTextSecondary,
    onTertiary: AppColors.fieldBackground,
    tertiaryContainer: AppColors.fieldBorder,
    onTertiaryContainer: AppColors.fieldTextPrimary,
    error: AppColors.fieldTextPrimary,
    onError: AppColors.fieldBackground,
    errorContainer: AppColors.fieldBorder,
    onErrorContainer: AppColors.fieldTextPrimary,
    surface: AppColors.fieldBackground,
    onSurface: AppColors.fieldTextPrimary,
    onSurfaceVariant: AppColors.fieldTextSecondary,
    surfaceDim: AppColors.fieldBackground,
    surfaceBright: AppColors.fieldBorder,
    surfaceContainerLowest: AppColors.fieldBackground,
    surfaceContainerLow: AppColors.fieldSurface,
    surfaceContainer: AppColors.fieldSurface,
    surfaceContainerHigh: AppColors.fieldSurfaceRaised,
    surfaceContainerHighest: Color(0xFF220000),
    outline: AppColors.fieldControlBorder,
    outlineVariant: AppColors.fieldBorder,
    shadow: AppColors.fieldBackground,
    scrim: AppColors.fieldBackground,
    inverseSurface: AppColors.fieldTextSecondary,
    onInverseSurface: AppColors.fieldBackground,
    inversePrimary: AppColors.fieldBackground,
    surfaceTint: AppColors.fieldBackground,
  );

  static final ThemeData fieldTheme = _withTokens(
    ThemeData(
      fontFamily: _family,
      colorScheme: fieldColorScheme,
      primaryColor: AppColors.fieldTextPrimary,
      scaffoldBackgroundColor: AppColors.fieldBackground,
      canvasColor: AppColors.fieldBackground,
      cardColor: AppColors.fieldSurface,
      dividerColor: AppColors.fieldBorder,
      hintColor: AppColors.fieldTextSecondary,
      disabledColor: AppColors.fieldTextDisabled,
      unselectedWidgetColor: AppColors.fieldTextSecondary,
      hoverColor: const Color(0x1FFF0000),
      focusColor: const Color(0x1FFF0000),
      highlightColor: const Color(0x1FFF0000),
      splashColor: const Color(0x33FF0000),
      shadowColor: AppColors.fieldBackground,
      secondaryHeaderColor: AppColors.fieldSurface,
      appBarTheme: const AppBarTheme(
        backgroundColor: AppColors.fieldBackground,
